//! AppArmor 4.0 Mandatory Access Control (MAC) profile generator for Cordon.

use crate::domain::CordonProfile;
use crate::error::CordonError;
use crate::ports::AppArmorCompilerPort;

/// Fail-closed deny-all profile emitted when interpolated entries fail validation (anti-injection).
const FAIL_CLOSED_PROFILE: &str =
    "# Generated by PyCentric Cordon (Type-Safe Rust MAC Engine) - Do not hand-edit
# ERROR: profile input failed AppArmor entry validation; emitting deny-all fail-closed policy.
abi <abi/4.0>,
#include <tunables/global>

profile cordon_invalid /usr/local/bin/agent-shell flags=(attach_disconnected,mediate_deleted) {
  deny /** rwlkmx,
}
";

/// Validates a single entry interpolated into the AppArmor profile DSL (paths, globs, attach path).
///
/// Rejects DSL metacharacters and separators (`,`, `"`, `{`, `}`, newlines, whitespace) that could
/// terminate the current rule or inject new rules. The `@{HOME}` variable literal and glob
/// wildcards (`*`, `?`, `[`, `]`) are permitted.
pub fn validate_apparmor_entry(entry: &str) -> Result<(), CordonError> {
    if entry.is_empty() {
        return Err(CordonError::InvalidInput(
            "AppArmor entry cannot be empty".to_owned(),
        ));
    }
    let stripped = entry.replace("@{HOME}", "");
    for ch in stripped.chars() {
        if ch.is_ascii_alphanumeric()
            || matches!(
                ch,
                '/' | '.' | '_' | '-' | '+' | '*' | '?' | '[' | ']' | '~'
            )
        {
            continue;
        }
        return Err(CordonError::InvalidInput(format!(
            "Invalid character '{ch}' in AppArmor entry '{entry}': only '@{{HOME}}', glob wildcards (* ? []), and [A-Za-z0-9/._-+~] are permitted"
        )));
    }
    Ok(())
}

fn validate_apparmor_profile_inputs(
    profile: &CordonProfile,
    attach_path: &str,
) -> Result<(), CordonError> {
    if profile.name.is_empty()
        || !profile
            .name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
    {
        return Err(CordonError::InvalidInput(format!(
            "Invalid profile name '{}' for AppArmor rendering",
            profile.name
        )));
    }
    validate_apparmor_entry(attach_path)?;
    for binary in &profile.denied_binaries {
        validate_apparmor_entry(binary)?;
    }
    for protected in &profile.protected_paths {
        validate_apparmor_entry(protected)?;
    }
    Ok(())
}

/// Renders a valid AppArmor 4.0 MAC profile from a [`CordonProfile`], rejecting any interpolated
/// entry that could inject AppArmor DSL ([`CordonError::InvalidInput`]).
///
/// Enforces:
/// - `userns,` and `mount,` permissions required by Bubblewrap (`bwrap`)
/// - `/usr/bin/bwrap ix,` inheritance so child processes remain confined
/// - `deny ... x` on blacklisted binaries and writable temp directories (BYOB defense)
/// - `deny ... rwlkmx` on sensitive credential directories and CA private keys
/// - `deny ... rwlkmx` on host Unix sockets (systemd private bus, D-Bus, keyring/gcr/gnupg agents,
///   Docker daemon socket) per CH-03
pub fn try_render_apparmor_profile(
    profile: &CordonProfile,
    attach_path: &str,
) -> Result<String, CordonError> {
    validate_apparmor_profile_inputs(profile, attach_path)?;

    let mut lines: Vec<String> = vec![
        "# Generated by PyCentric Cordon (Type-Safe Rust MAC Engine) - Do not hand-edit".to_owned(),
        "abi <abi/4.0>,".to_owned(),
        "#include <tunables/global>".to_owned(),
        String::new(),
        format!(
            "profile cordon_{} {} flags=(attach_disconnected,mediate_deleted) {{",
            profile.name.replace('-', "_"),
            attach_path
        ),
        "  #include <abstractions/base>".to_owned(),
        "  #include <abstractions/nameservice>".to_owned(),
        "  #include <abstractions/ssl_certs>".to_owned(),
        String::new(),
        "  # 1. Baseline allow for normal developer toolchain and libraries".to_owned(),
        "  / r,".to_owned(),
        "  /** r,".to_owned(),
        "  /usr/** rix,".to_owned(),
        "  /bin/** rix,".to_owned(),
        "  /lib/** mr,".to_owned(),
        "  /lib64/** mr,".to_owned(),
        "  /opt/** rix,".to_owned(),
        "  @{HOME}/** rwk,".to_owned(),
        "  @{HOME}/.local/** rix,".to_owned(),
        "  @{HOME}/.cargo/bin/** rix,".to_owned(),
        "  @{HOME}/**/node_modules/.bin/** rix,".to_owned(),
        "  @{HOME}/**/target/** rix,".to_owned(),
        "  @{HOME}/**/.venv/bin/** rix,".to_owned(),
        "  /tmp/** rwkl,".to_owned(),
        "  /var/tmp/** rwkl,".to_owned(),
        "  /dev/shm/** rwkl,".to_owned(),
        String::new(),
        "  # 2. Bubblewrap namespace creation requirements (AppArmor 4.0, FR-3.4 & EC-06)"
            .to_owned(),
        "  userns,".to_owned(),
        "  mount,".to_owned(),
        "  remount,".to_owned(),
        "  umount,".to_owned(),
        "  pivot_root,".to_owned(),
        "  capability sys_chroot,".to_owned(),
        "  capability setpcap,".to_owned(),
        "  capability setuid,".to_owned(),
        "  capability setgid,".to_owned(),
        "  capability dac_override,".to_owned(),
        "  /usr/bin/bwrap ix,".to_owned(),
        String::new(),
        "  # 3. Explicit privilege, capability, and ptrace containment (FR-3.4)".to_owned(),
        "  deny capability net_admin,".to_owned(),
        "  deny capability net_raw,".to_owned(),
        "  deny capability sys_admin,".to_owned(),
        "  deny capability sys_module,".to_owned(),
        "  deny capability sys_rawio,".to_owned(),
        "  deny capability sys_ptrace,".to_owned(),
        "  deny capability sys_boot,".to_owned(),
        "  deny capability mac_admin,".to_owned(),
        "  deny capability mac_override,".to_owned(),
        "  deny ptrace,".to_owned(),
        "  deny signal peer=unconfined,".to_owned(),
        String::new(),
        "  # 4. Network rules: allow TCP/UDP streams, block raw packet sockets (FR-3.4)".to_owned(),
        "  network inet stream,".to_owned(),
        "  network inet6 stream,".to_owned(),
        "  network inet dgram,".to_owned(),
        "  network inet6 dgram,".to_owned(),
        "  network unix stream,".to_owned(),
        "  network unix dgram,".to_owned(),
        "  network netlink raw,".to_owned(),
        "  deny network raw,".to_owned(),
        String::new(),
        "  # 5. BYOB Prevention: deny execution in writable temp/shm directories (FR-3.2)"
            .to_owned(),
        "  deny /tmp/** x,".to_owned(),
        "  deny /var/tmp/** x,".to_owned(),
        "  deny /dev/shm/** x,".to_owned(),
        "  deny /run/user/** x,".to_owned(),
        String::new(),
        "  # 6. Blacklisted high-risk executables (FR-3.1)".to_owned(),
    ];

    for binary in &profile.denied_binaries {
        lines.push(format!("  deny {binary} x,"));
    }

    lines.push(String::new());
    lines.push("  # 7. Sensitive credential and CA private key protection (FR-3.3)".to_owned());
    for protected in &profile.protected_paths {
        lines.push(format!("  deny {protected} rwlkmx,"));
    }

    lines.push(String::new());
    lines.push(
        "  # 7b. CH-03: Unix socket host-service isolation (systemd, D-Bus, keyring, Docker)"
            .to_owned(),
    );
    lines.push("  deny /run/user/**/systemd/** rwlkmx,".to_owned());
    lines.push("  deny /run/user/**/bus rwlkmx,".to_owned());
    lines.push("  deny /run/user/**/keyring/** rwlkmx,".to_owned());
    lines.push("  deny /run/user/**/gcr/** rwlkmx,".to_owned());
    lines.push("  deny /run/user/**/gnupg/** rwlkmx,".to_owned());
    lines.push("  deny /run/dbus/** rwlkmx,".to_owned());
    lines.push("  deny /run/docker.sock rwlkmx,".to_owned());
    lines.push("  deny /var/run/docker.sock rwlkmx,".to_owned());

    lines.push(String::new());
    lines.push("  # 8. Self-tampering prevention (FR-3.5)".to_owned());
    lines.push(format!("  deny {attach_path} wkl,"));
    lines.push("  deny /usr/local/bin/agent-sandbox wkl,".to_owned());
    lines.push("  deny /usr/local/bin/cordon wkl,".to_owned());
    lines.push("  deny /etc/apparmor* wkl,".to_owned());
    lines.push("  deny /etc/apparmor.d/** rwlkmx,".to_owned());
    lines.push("  deny /sys/kernel/security/apparmor/** wkl,".to_owned());

    lines.push("}".to_owned());
    lines.push(String::new());
    Ok(lines.join("\n"))
}

/// Renders the AppArmor 4.0 profile, emitting a deny-all fail-closed policy when any interpolated
/// entry fails [`validate_apparmor_entry`] (the typed error surface is [`try_render_apparmor_profile`]).
pub fn render_apparmor_profile(profile: &CordonProfile, attach_path: &str) -> String {
    match try_render_apparmor_profile(profile, attach_path) {
        Ok(rendered) => rendered,
        Err(_) => FAIL_CLOSED_PROFILE.to_owned(),
    }
}

/// Default stateless implementation of [`AppArmorCompilerPort`].
#[derive(Debug, Default, Clone, Copy)]
pub struct AppArmorProfileCompiler;

impl AppArmorCompilerPort for AppArmorProfileCompiler {
    fn render_apparmor_profile(&self, profile: &CordonProfile, attach_path: &str) -> String {
        render_apparmor_profile(profile, attach_path)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::profiles::get_profile;

    #[test]
    fn clean_entries_and_home_glob_are_accepted() {
        for entry in [
            "@{HOME}/.ssh/**",
            "/usr/bin/nc",
            "/usr/bin/nc*",
            "/opt/[ab]/tool",
            "/usr/local/bin/agent-shell",
        ] {
            assert!(
                validate_apparmor_entry(entry).is_ok(),
                "expected '{entry}' to validate"
            );
        }
    }

    #[test]
    fn hostile_entries_are_rejected() {
        for hostile in [
            "deny } x,",
            "foo\" bar",
            "foo,bar",
            "foo\nbar",
            "foo\rbar",
            "foo bar",
            "/tmp/x} y",
            "@{EVIL}/x",
        ] {
            assert!(
                matches!(
                    validate_apparmor_entry(hostile),
                    Err(CordonError::InvalidInput(_))
                ),
                "expected rejection for '{hostile}'"
            );
        }
    }

    #[test]
    fn try_render_rejects_hostile_profile_entries() {
        let Ok(mut profile) = get_profile("ai-agent") else {
            panic!("ai-agent profile missing");
        };
        let baseline =
            try_render_apparmor_profile(&profile, "/usr/local/bin/agent-shell").unwrap_or_default();
        assert!(baseline.contains("deny /run/dbus/** rwlkmx,"));
        assert!(baseline.contains("deny /run/docker.sock rwlkmx,"));

        profile
            .denied_binaries
            .push("evil } x,\ndeny /pwn rw".to_owned());
        assert!(matches!(
            try_render_apparmor_profile(&profile, "/usr/local/bin/agent-shell"),
            Err(CordonError::InvalidInput(_))
        ));

        let Ok(mut protected_profile) = get_profile("ai-agent") else {
            panic!("ai-agent profile missing");
        };
        protected_profile
            .protected_paths
            .push("@{HOME}/.ssh/** rwlkmx,\n  / pwn".to_owned());
        assert!(matches!(
            try_render_apparmor_profile(&protected_profile, "/usr/local/bin/agent-shell"),
            Err(CordonError::InvalidInput(_))
        ));

        let Ok(clean) = get_profile("ai-agent") else {
            panic!("ai-agent profile missing");
        };
        assert!(matches!(
            try_render_apparmor_profile(&clean, "/usr/bin/evil\" wkl,\n  / pwn"),
            Err(CordonError::InvalidInput(_))
        ));
    }

    #[test]
    fn infallible_render_fails_closed_without_injecting_dsl() {
        let Ok(mut profile) = get_profile("ai-agent") else {
            panic!("ai-agent profile missing");
        };
        let hostile = "evil } x,".to_owned();
        profile.denied_binaries.push(hostile.clone());
        let rendered = render_apparmor_profile(&profile, "/usr/local/bin/agent-shell");
        assert!(!rendered.contains(&hostile), "hostile DSL must not leak");
        assert!(rendered.contains("deny /** rwlkmx,"));
        assert!(rendered.contains("profile cordon_invalid"));
    }
}
